<?php require 'config.php'; $msg=''; if($_SERVER['REQUEST_METHOD']=='POST'){ $email=trim($_POST['email']);$p=$_POST['password'];$st=$conn->prepare("SELECT * FROM users WHERE email=?");$st->bind_param("s",$email);$st->execute();$u=$st->get_result()->fetch_assoc();if($u&&password_verify($p,$u['password'])){$_SESSION['user']=$u;header('Location: dashboard.php');exit;} $msg='Invalid email or password.';} ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="formpage"><div class="panel"><h1>Login</h1><?php if($msg):?><p class="error"><?=$msg?></p><?php endif;?><form method="post"><input name="email" type="email" placeholder="Email" required><input name="password" type="password" placeholder="Password" required><button class="btn">Login</button></form><p>New user? <a href="register.php">Create account</a></p><a href="index.php">Back to home</a></div></main></body></html>